"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9495],{99495:e=>{e.exports=JSON.parse('{"slug":"samsung-rekord-pamyat-smartfony-ceny","locale":"ko","title":"메모리 부족 속에 삼성의 분기 이익이 사상 최대 $80십억을 기록했고 스마트폰은 비싸지고 있습니다","description":"삼성은 2026년 III분기 영업이익 107,4조 원을 기록했습니다. AI 메모리 때문에 세계와 러시아에서 스마트폰이 비싸지는 이유를 살펴봅니다.","blocks":[{"id":"b001","kind":"paragraph","text":"삼성전자는 2026년 시월 8일 III분기 영업이익을 107,4조 원, 약 $80,2십억으로 추정했습니다. 전년의 12,2조 원보다 거의 9배입니다. 매출은 2배 이상 늘어 약 195조 원이 됐습니다. 종전 최고치는 2026년 II분기의 89,5조 원이었습니다. 분석가들은 약 108조 원으로 조금 더 높게 예상했습니다."},{"id":"b002","kind":"paragraph","text":"삼성의 이익을 끌어올린 것은 메모리, 특히 인공지능 서버용 메모리입니다. 휴대전화\xb7노트북용 일반 메모리와 같은 공장에서 만들지만 훨씬 비싸게 팝니다. 식당이 케이크에 지불하는 돈이 상점이 빵에 지불하는 돈의 3배인 제과점과 비슷합니다. 오븐은 같으니 빵을 덜 굽게 됩니다. 새 공장을 짓는 데는 여러 해가 걸립니다. 서버용 대신 일반 메모리를 생산해 포기하는 이익을 기회비용이라고 합니다."},{"id":"b003","kind":"paragraph","text":"모바일 메모리는 2026년 II분기에 2025년 IV분기 대비 거의 3배 비싸졌습니다. 2026년 초 이후 세계 스마트폰 모델의 40% 이상이 평균 15% 올랐습니다. 2026년 신제품은 전년 제품보다 25% 비쌉니다. 생산량과 구매량은 줄고 있습니다. 카운터포인트 리서치는 유월 전망을 낮춰 2026년 출하량이 13,9% 감소한 1,08십억 대가 될 것으로 봅니다. 갤럭시를 만드는 삼성 부문은 높은 메모리 가격 때문에 II분기 처음으로 0,7조 원의 영업손실을 냈습니다."},{"id":"b004","kind":"paragraph","text":"러시아에서는 2026년 37주 동안 스마트폰 15,2백만 대가 팔려 전년보다 11,7% 줄었습니다. 평균 구매액은 7,6% 오른 25,8천 루블이며 이는 가격표와 소비자의 제품 선택 모두에 영향을 받습니다. 저가 모델은 메모리를 줄입니다. 구월 출시된 레드미 17은 18천 루블부터 시작하며 RAM은 4GB입니다. 구월 29일부터 시월 5일까지 러시아 스마트폰 가격은 1,1%, TV는 1% 올랐습니다. 수입제품이며 시월 1일부터 6일까지 달러 공식 환율도 83,56루블에서 84,93루블로 올라 주간 가격 상승이 메모리 때문만은 아닐 수 있습니다."},{"id":"b005","kind":"paragraph","text":"트렌드포스는 2026년 IV분기 일반 메모리 계약가격이 III분기보다 추가로 10–15%, 낸드플래시는 15–20% 오를 것으로 예상합니다. 삼성 메모리 부문 김재준 부사장은 2026년 전체와 2027년 대부분, 어쩌면 2028년까지 부족이 이어질 것으로 봅니다. SK하이닉스 곽노정 대표는 2027년이 업계 역사상 메모리 공급에 최악의 해가 될 수도 있다고 말했습니다."},{"id":"b006","kind":"paragraph","text":"지금 휴대전화를 사면 전년보다 비쌉니다. 구매를 미룰 수는 있지만 제조업체들은 2027년에도 메모리가 부족할 것으로 예상합니다. 루블 강세는 가격 상승을 완화하고 약세는 가속합니다."},{"id":"b007","kind":"heading","text":"2026년 스마트폰이 비싸지는 이유는 무엇인가요?"},{"id":"b008","kind":"paragraph","text":"메모리 부족 때문입니다. 제조업체들이 공장을 고가의 AI 서버용 메모리로 전환해 휴대전화용 일반 메모리가 부족해집니다. 모바일 메모리는 2026년 II분기에 2025년 말 대비 거의 3배 올랐고 세계 스마트폰 가격은 연초 이후 평균 15% 상승했습니다."},{"id":"b009","kind":"heading","text":"러시아 스마트폰 가격은 얼마나 올랐나요?"},{"id":"b010","kind":"paragraph","text":"2026년 37주 동안 러시아에서 구매한 스마트폰 평균가격은 7,6% 오른 25,8천 루블이 됐으며 판매대수는 11,7% 줄었습니다. 구월 29일부터 시월 5일까지의 가격 상승률은 1,1%입니다."},{"id":"b011","kind":"heading","text":"메모리 부족은 언제 끝나나요?"},{"id":"b012","kind":"paragraph","text":"제조업체들은 종료 시점을 보장하지 않습니다. 삼성은 2026년 전체와 2027년 대부분, 어쩌면 2028년까지 부족할 것으로 봅니다. SK하이닉스 대표는 2027년이 업계 역사상 메모리 공급에 최악의 해가 될 수도 있다고 말했습니다."}],"sources":[{"label":"Samsung Estimates Record $80 Billion Operating Profit in Q3 2026","url":"https://sammyguru.com/samsung-estimates-record-80-billion-operating-profit-q3-2026/"},{"label":"Samsung forecasts record third-quarter profit of $80 billion as AI boom fuels chip demand","url":"https://www.cnbc.com/2026/10/08/samsung-q3-earnings.html"},{"label":"Samsung\'s quarterly profit jumped ninefold to roughly $80 billion on AI chips","url":"https://startupfortune.com/samsungs-quarterly-profit-jumped-ninefold-to-roughly-80-billion-on-ai-chips/"},{"label":"The Samsung unit behind its Galaxy phones just reported its first quarterly loss ever","url":"https://www.phonearena.com/news/samsung-mobile-experience-unit-first-quarterly-loss_id182207"},{"label":"앞으로 더 악화될 수 있습니다. 세계 스마트폰 가격의 걷잡을 수 없는 상승","url":"https://www.cnews.ru/news/top/2026-09-04_dalshe_budet_huzhev_mire"},{"label":"Memory Crunch Freezes Smartphone Market: 2026 Shipments Seen Plunging 13.9%","url":"https://finance.biggo.com/news/o46al54B6tLPsnrZsogu"},{"label":"AI Server Demand Sustains Memory Contract Price Increases in 4Q26","url":"https://www.trendforce.com/presscenter/news/20260930-13258.html"},{"label":"러시아 소비자들의 스마트폰 구매량이 줄었습니다","url":"https://3dnews.ru/1149266"},{"label":"29 구월에서 5 시월까지 러시아의 인플레이션","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"},{"label":"Samsung warns the RAM shortage will last through 2027, maybe 2028","url":"https://www.pcworld.com/article/3203764/samsung-warns-the-ram-shortage-will-last-through-2027-maybe-2028.html"},{"label":"SK Hynix Warns Memory Shortage Will Be Worst Ever in 2027","url":"https://propakistani.pk/2026/07/13/sk-hynix-warns-memory-shortage-will-be-worst-ever-in-2027/"}],"sourceBodySha256":"9109ae1c3a0a697fc17c90fd75c97bd35553c9ab1d7901b4a84036a4db6a8302"}')}}]);